import React, { useEffect, useRef, useState } from 'react';
import BpmnModelerLib from 'bpmn-js/dist/bpmn-modeler.production.min.js';
import 'bpmn-js/dist/assets/diagram-js.css';
import 'bpmn-js/dist/assets/bpmn-font/css/bpmn.css';
import ThemeToggle from '../components/ThemeToggle';
import { useTheme } from '../context/ThemeContext';

const initialDiagram = `<?xml version="1.0" encoding="UTF-8"?>
<bpmn:definitions xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL" xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI" xmlns:dc="http://www.omg.org/spec/DD/20100524/DC" id="Definitions_1" targetNamespace="http://bpmn.io/schema/bpmn">
    <bpmn:process id="Process_1" isExecutable="false">
    </bpmn:process>
    <bpmndi:BPMNDiagram id="BPMNDiagram_1">
    <bpmndi:BPMNPlane id="BPMNPlane_1" bpmnElement="Process_1">
    </bpmndi:BPMNPlane>
    </bpmndi:BPMNDiagram>
</bpmn:definitions>`;

const BPMNPage = () => {
    const containerRef = useRef(null);
    const modelerRef = useRef(null);
    const fileInputRef = useRef(null);
    const [notification, setNotification] = useState('');
    const { theme } = useTheme();

    useEffect(() => {
        if (!modelerRef.current && containerRef.current) {
            // Intialize BPMN Modeler
            modelerRef.current = new BpmnModelerLib({
                container: containerRef.current,
                additionalModules: [{
                    // Disable default zoom scroll to prevent accidental zooming while scrolling page
                    zoomScroll: ['value', {
                        toggle: function() {}, 
                        scroll: function() {}  
                    }]
                }]
            });

            const modeler = modelerRef.current;

            // Hook for applying custom CSS classes (Legacy Dark Mode Support)
            modeler.on('shape.added', (e) => {
                const element = e.element;
                const canvas = modeler.get('canvas');

                // 1. DataObject and DataStore (Fix for Dark Mode fills)
                if (['bpmn:DataObjectReference', 'bpmn:DataStoreReference'].includes(element.type)) {
                    canvas.addMarker(element, 'dark-fill-fix');
                }

                // 2. Message Intermediate Throw Event (Specific styling)
                if (element.type === 'bpmn:IntermediateThrowEvent') {
                    const bo = element.businessObject;
                    if (bo.eventDefinitions && bo.eventDefinitions.some(ed => ed.$type === 'bpmn:MessageEventDefinition')) {
                         canvas.addMarker(element, 'message-event-styled');
                    }
                }
            });

            // Create initial diagram
            openDiagram(initialDiagram);
        }

        return () => {
             // Cleanup if needed, though destroying modeler on unmount is good practice
            if (modelerRef.current) {
                modelerRef.current.destroy();
                modelerRef.current = null;
            }
        };
    }, []);

    const openDiagram = async (xml) => {
        try {
            await modelerRef.current.importXML(xml);
            const canvas = modelerRef.current.get('canvas');
            canvas.zoom('fit-viewport');
        } catch (err) {
            console.error(err);
            showNotify('Erro ao carregar diagrama.');
        }
    };

    const showNotify = (msg) => {
        setNotification(msg);
        setTimeout(() => setNotification(''), 3000);
    };

    const createNewDiagram = () => {
        if(confirm('Tem certeza que deseja criar um novo diagrama? As alterações não salvas serão perdidas.')) {
            openDiagram(initialDiagram);
            showNotify('Novo diagrama criado.');
        }
    };

    const undo = () => modelerRef.current.get('commandStack').undo();
    const redo = () => modelerRef.current.get('commandStack').redo();

    // State for Dropdown and Filename
    const [isDropdownOpen, setDropdownOpen] = useState(false);
    const [filename, setFilename] = useState('diagrama');
    const dropdownRef = useRef(null);

    // Close dropdown when clicking outside
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
                setDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const toggleDropdown = () => setDropdownOpen(!isDropdownOpen);

    const handleAction = (action) => {
        setDropdownOpen(false);
        action();
    };

    const handleFileLoad = (e) => {
        const file = e.target.files[0];
        if (file) {
            const name = file.name.replace(/\.[^/.]+$/, "");
            setFilename(name);
            
            const reader = new FileReader();
            reader.onload = (e) => {
                openDiagram(e.target.result);
                showNotify('Diagrama carregado com sucesso!');
            };
            reader.readAsText(file);
        }
    };

    const saveXML = async () => {
        try {
            const { xml } = await modelerRef.current.saveXML({ format: true });
            const blob = new Blob([xml], { type: 'application/xml' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `${filename}.bpmn`;
            a.click();
            window.URL.revokeObjectURL(url);
            showNotify('Diagrama salvo (XML)!');
        } catch (err) {
            console.error(err);
            showNotify('Erro ao salvar XML.');
        }
    };

    const saveSVG = async () => {
        try {
            const { svg } = await modelerRef.current.saveSVG();
            const blob = new Blob([svg], { type: 'image/svg+xml' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `${filename}.svg`;
            a.click();
            window.URL.revokeObjectURL(url);
            showNotify('Imagem salva (SVG)!');
        } catch (err) {
            console.error(err);
            showNotify('Erro ao salvar SVG.');
        }
    };

    return (
        <div className="flex flex-col h-screen overflow-hidden bg-gray-50 dark:bg-[#121212]">
            {/* Custom Navbar for BPMN Page - Matching AppNavbar Layout exactly */}
            <nav 
                className="shrink-0 w-full z-50 border-b backdrop-blur-md transition-colors duration-300"
                style={{ 
                    backgroundColor: 'var(--bg-card)', 
                    borderColor: 'var(--border-card)',
                    height: '80px'
                }}
            >
                <div className="w-full px-6 h-20 flex items-center justify-between">
                    
                    {/* Left: Logo */}
                    <a href="/" className="flex items-center gap-3 group text-decoration-none focus:outline-none shrink-0">
                        <div className="relative">
                            <div className="absolute inset-0 bg-orange-500 blur-lg opacity-20 rounded-full group-hover:opacity-40 transition-opacity"></div>
                             {/* Import logo from assets if possible, or use Next Image with imported object */}
                             <img 
                                src={require('../assets/logo.png').default.src} 
                                alt="Business Tools" 
                                className="h-8 w-auto relative z-10" 
                            />
                        </div>
                        <span className="font-bold text-xl tracking-tight transition-colors" style={{ color: 'var(--text-main)' }}>
                            Business <span className="text-orange-500">tools</span>
                        </span>
                    </a>

                    {/* Center: File Renaming */}
                    <div className="hidden md:flex absolute left-1/2 transform -translate-x-1/2 items-center justify-center">
                         <div className="flex items-center gap-2 px-4 py-2 rounded-xl bg-gray-50 dark:bg-white/5 border border-gray-100 dark:border-[#333] hover:border-gray-200 dark:hover:border-gray-600 transition-all group">
                            <i className="fas fa-pen text-gray-400 text-xs group-hover:text-orange-500 transition-colors"></i>
                            <input 
                                type="text" 
                                value={filename}
                                onChange={(e) => setFilename(e.target.value)}
                                className="bg-transparent border-none outline-none text-center font-medium text-gray-700 dark:text-gray-200 placeholder-gray-400 w-48 focus:w-64 transition-all"
                                placeholder="Nome do arquivo"
                            />
                             <span className="text-gray-400 text-sm font-medium select-none">.bpmn</span>
                        </div>
                    </div>

                    {/* Right: Actions (Theme Toggle + Menu) */}
                    <div className="flex items-center gap-6 shrink-0">
                        
                        {/* Theme Toggle Element */}
                        <ThemeToggle />

                        {/* Menu Dropdown */}
                        <div className="relative" ref={dropdownRef}>
                            <button 
                                onClick={toggleDropdown}
                                className="flex items-center gap-2 text-xs font-bold uppercase tracking-wider transition-colors py-2"
                                style={{ color: 'var(--text-muted)' }}
                            >
                                Menu
                                <i className={`fas fa-chevron-down text-[10px] transition-transform ${isDropdownOpen ? 'rotate-180' : ''}`}></i>
                            </button>

                            {isDropdownOpen && (
                                <div 
                                    className="absolute right-0 top-full mt-2 w-64 bg-white dark:bg-[#1e1e1e] border border-gray-200 dark:border-[#333] rounded-xl shadow-2xl z-50 overflow-hidden animate-fade-in-up origin-top-right"
                                    style={{ backgroundColor: theme === 'dark' ? '#1e1e1e' : '#ffffff' }}
                                >
                                    <div className="p-2">
                                        <button onClick={() => handleAction(createNewDiagram)} className="w-full text-left px-4 py-3 rounded-lg hover:bg-orange-50 dark:hover:bg-orange-900/10 text-gray-700 dark:text-gray-200 text-sm flex items-center gap-3 transition-colors group">
                                            <div className="w-8 h-8 rounded-full bg-orange-100 dark:bg-orange-900/30 flex items-center justify-center text-orange-500 group-hover:scale-110 transition-transform">
                                                <i className="fas fa-file"></i>
                                            </div>
                                            <div>
                                                <div className="font-semibold text-gray-900 dark:text-gray-100">Novo</div>
                                                <div className="text-xs text-gray-500 dark:text-gray-400">Começar do zero</div>
                                            </div>
                                        </button>
                                        
                                        <button onClick={() => { setDropdownOpen(false); fileInputRef.current.click(); }} className="w-full text-left px-4 py-3 rounded-lg hover:bg-blue-50 dark:hover:bg-blue-900/10 text-gray-700 dark:text-gray-200 text-sm flex items-center gap-3 transition-colors group">
                                             <div className="w-8 h-8 rounded-full bg-blue-100 dark:bg-blue-900/30 flex items-center justify-center text-blue-500 group-hover:scale-110 transition-transform">
                                                <i className="fas fa-folder-open"></i>
                                            </div>
                                            <div>
                                                <div className="font-semibold text-gray-900 dark:text-gray-100">Abrir</div>
                                                <div className="text-xs text-gray-500 dark:text-gray-400">Importar arquivo local</div>
                                            </div>
                                        </button>
                                        
                                        <div className="h-px bg-gray-100 dark:bg-[#333] my-2"></div>
                                        
                                        <div className="px-4 py-1 text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Exportar como</div>
                                        
                                        <button onClick={() => handleAction(saveXML)} className="w-full text-left px-4 py-2 rounded-lg hover:bg-gray-50 dark:hover:bg-white/5 text-gray-700 dark:text-gray-200 text-sm flex items-center gap-3 transition-colors text-sm">
                                            <i className="fas fa-code w-5 text-center text-gray-400"></i> XML (BPMN 2.0)
                                        </button>
                                        <button onClick={() => handleAction(saveSVG)} className="w-full text-left px-4 py-2 rounded-lg hover:bg-gray-50 dark:hover:bg-white/5 text-gray-700 dark:text-gray-200 text-sm flex items-center gap-3 transition-colors text-sm">
                                            <i className="fas fa-image w-5 text-center text-gray-400"></i> Imagem (SVG)
                                        </button>
                                    </div>
                                </div>
                            )}
                        </div>
                        
                        <input type="file" ref={fileInputRef} accept=".bpmn,.xml" onChange={handleFileLoad} className="hidden" />
                    </div>
                </div>
            </nav>

            {/* Modeler Container */}
            <div className="flex-grow relative w-full h-full overflow-hidden">
                 <div ref={containerRef} className="w-full h-full canvas-container"></div>
                 
                 {/* 
                   Undo/Redo Integrated into Palette VISUALLY 
                   We position them exactly where the top of the palette starts (top: 20px, left: 20px)
                   and we use CSS to push the actual palette down via index.css 'top: 120px' 
                 */}
                <div className="absolute top-[20px] left-[20px] w-[48px] flex flex-col gap-2 z-10">
                    <div className="bg-white dark:bg-[#1e1e1e] border border-gray-200 dark:border-[#333] rounded-[8px] shadow-sm flex flex-col overflow-hidden">
                         <button onClick={undo} className="w-full h-[40px] flex items-center justify-center hover:bg-orange-50 dark:hover:bg-white/5 text-gray-600 dark:text-gray-400 hover:text-orange-500 transition-all" title="Desfazer">
                            <i className="fas fa-undo text-sm"></i>
                        </button>
                        <div className="h-px w-full bg-gray-100 dark:bg-[#333]"></div>
                        <button onClick={redo} className="w-full h-[40px] flex items-center justify-center hover:bg-orange-50 dark:hover:bg-white/5 text-gray-600 dark:text-gray-400 hover:text-orange-500 transition-all" title="Refazer">
                            <i className="fas fa-redo text-sm"></i>
                        </button>
                    </div>
                 </div>
            </div>

            {/* Notification Toast */}
            {notification && (
                <div className="fixed bottom-6 right-6 z-50 animate-fade-in-up">
                    <div className="bg-gray-900 dark:bg-white text-white dark:text-gray-900 px-6 py-3 rounded-lg shadow-xl flex items-center gap-3 border border-gray-700 dark:border-gray-200">
                        <i className="fas fa-info-circle text-orange-500"></i>
                        <span className="font-medium">{notification}</span>
                    </div>
                </div>
            )}
        </div>
    );
};

export default BPMNPage;
